from review import card,save,DATE
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2076';_,c=card(i);refs=c['references'];refs[0]['locator']='APPROX/RANDOM 2024, article 56: model, Theorem 1, Conjecture 4 and definitions of global Kawasaki dynamics and analytic threshold read.'
refs.append(dict(id='journal',title='Fast and Slow Mixing of the Kawasaki Dynamics on Bounded-Degree Graphs — final version',authors='Aiya Kuchukova, Marcus Pappik, Will Perkins, Corrine Yap',year=2025,url='https://arxiv.org/abs/2405.06209v2',locator='Final published version, 24 November 2025; Random Structures & Algorithms 67(4), e70038, DOI 10.1002/rsa.70038. Theorem 1.1, Conjecture 1.4, Definition 2.3, Definitions 2.15–2.16 and Lemma 2.18 read. The optimal bound remains conjectured; the analytic and uniqueness thresholds can differ.'))
save(i,dict(title='Optimal mixing of global Kawasaki dynamics on bounded-degree graphs',formal='Fix an integer Δ≥3, inverse temperature β≥0 and magnetization η∈[−1,1]. If β<β_u(Δ), or if β>β_u(Δ) and |η|>η_a(Δ,β), must the global Kawasaki dynamics for the fixed-magnetization ferromagnetic Ising model mix in O(n log n) discrete updates on every n-vertex graph of maximum degree at most Δ? The implicit constant may depend on the fixed Δ,β,η, but not on n or the graph.',definitions='For a finite undirected simple graph G=(V,E), n=|V|, put k=⌊n(1+η)/2⌋ and Ω_k={σ∈{−1,+1}^V: |{v:σ_v=+1}|=k}. Let m_G(σ) count edges with equal endpoint spins, and let μ̂(σ)=exp(βm_G(σ))/Σ_{τ∈Ω_k}exp(βm_G(τ)). One global Kawasaki step chooses a uniformly random +1 vertex u and a uniformly random −1 vertex v, proposes exchanging their spins, and accepts with probability min{1,exp(β[m_G(σ′)−m_G(σ)])}; otherwise it stays at σ. The vertices need not be adjacent. For k=0 or n the chain has one state. With transition matrix P, τ_mix is the least integer s with max_{σ∈Ω_k}(1/2)Σ_τ|P^s(σ,τ)−μ̂(τ)|≤1/4. The O(n log n) assertion is asymptotic: constants C,n_0 exist such that τ_mix≤Cn log n for all n≥n_0 and all such graphs. This avoids irrelevant very small periodic instances of the unmodified chain. In the source’s monochromatic-edge normalization, β_u(Δ)=ln(Δ/(Δ−2)). For β≥β_u, define Z_G^τ(β,z)=Σ_{σ consistent with τ}z^{|{v:σ_v=+1}|}exp(βm_G(σ)), where τ pins spins on any subset of vertices. The analytic threshold λ_a(Δ,β) is the smallest a≥1 such that for every compact D⊂(a,∞) there is δ>0 for which Z_G^τ(β,z)≠0 whenever |z−λ|<δ for some λ∈D, uniformly over all maximum-degree-Δ graphs and all pinnings τ. On the infinite Δ-regular tree, take the Ising Gibbs measure obtained as the limit of finite balls with all-plus boundary spins, edge weight exp(β·1[equal spins]) and activity λ per plus spin. Let η_a(Δ,β) be its expected root spin at λ=λ_a(Δ,β). The conjecture excludes β=β_u and the boundary |η|=η_a.',question_type='yes_no',answer_criterion='Prove the uniform O(n log n) worst-start mixing bound for every fixed parameter triple in the stated regime, or refute it with an admissible fixed triple and a graph sequence whose mixing times exceed every constant multiple of n log n.',context_blocks=[b('The total number of plus spins stays fixed','A usual single-site Ising update can change the magnetization. Kawasaki updates exchange opposite spins and therefore preserve exactly k plus spins. The target measure is the Ising measure conditioned on that count.'),b('Global exchanges determine the time scale','A step can exchange distant vertices in any graph. Restricting exchanges to edges defines local Kawasaki dynamics, whose mixing can also be limited by transport across the graph. The conjecture concerns the global chain and counts one proposed exchange as one step.'),b('Quadratic mixing is already known','The source proves O(n²) mixing in the indicated regime. The open strengthening reduces that worst-case bound to O(n log n); efficient sampling by another algorithm alone would not establish it.', 'journal'),b('The two thresholds must remain distinct','The analytic threshold uses zero-freeness under every pinning, while the tree uniqueness threshold asks for uniqueness of a Gibbs measure. The final 2025 version proves that these thresholds can differ. Replacing η_a by the smaller uniqueness-based threshold would change the conjecture.', 'journal')],why='Would identify the sharp update-count scale for constrained Ising sampling throughout the source’s fast-mixing regime on arbitrary bounded-degree graphs.',progress=[dict(date='2024',text='The source proves an O(n²) upper bound and conjectures O(n log n) for global Kawasaki dynamics in this regime.',citation='primary'),dict(date='2025-11-24',text='The final published version retains the conjecture as Conjecture 1.4 and proves that the analytic and uniqueness thresholds need not coincide.',citation='journal')],references=refs,status='source_open',status_note='The 2024 conference paper and final 2025 journal version checked, with later-result searches through 12 September 2026. Conjecture 1.4 remains explicit in the final version; no subsequent resolution of this all-graphs O(n log n) target was located.',model_self_contained=True,requires_context=False,importance=imp(c,'A precise optimal-mixing conjecture for fixed-magnetization sampling on bounded-degree graphs.'),review_note='Recovered the truncated mixing bound, global Metropolis update, fixed-parameter asymptotics and analytic magnetization threshold. Defined the tree magnetization by the Gibbs measure to avoid relying on the source’s displayed recursion convention. Incorporated the final version’s threshold correction.',working_summary=sm(['Kawasaki dynamics samples Ising spin configurations while keeping the number of plus spins fixed.','Each global update exchanges two opposite spins, even when the vertices are far apart.','The conjecture asks for O(n log n) mixing on every bounded-degree graph in a specified temperature and magnetization regime.','The current source proves O(n²) mixing there.','The 2025 final version retains the conjecture and shows why its analytic threshold cannot simply be replaced by the tree uniqueness threshold.'],['primary','journal'])),notes=['Restored the O(n log n) target with graph-uniform, fixed-parameter quantifiers.','Defined global updates, stationary distribution, total-variation mixing and the analytic threshold.','Checked the final 2025 version and incorporated its separation of analytic and uniqueness thresholds.'],checked_sources=[r['url'] for r in refs]+['https://doi.org/10.1002/rsa.70038'])

i='TCS-2077';_,c=card(i);refs=c['references'];refs[0]['locator']='APPROX/RANDOM 2024, article 75: Sections 1, 2–2.1 and 4 read. The missing predicate is divisibility of a sparse polynomial by a fixed-total-degree polynomial. The field is Q and arithmetic operations have unit cost.'
refs.extend([dict(id='forbes',title='Deterministic Divisibility Testing via Shifted Partial Derivatives',authors='Michael A. Forbes',year=2015,url='https://www.ias.edu/sites/default/files/math/csdm/14-15/Forbes2015.pdf',locator='FOCS 2015: constant-degree divisor and sparse dividend quasipolynomial-time result; also discussed in Section 1.2 of the 2024 source.'),dict(id='bounded_individual',title='On Factorization of Sparse Polynomials of Bounded Individual Degree',authors='Aminadav Chuyoon, Amir Shpilka',year=2026,url='https://eccc.weizmann.ac.il/report/2026/036/',locator='Abstract, Theorem 1.9 and Section 1.3 read. The bound poly(n,d!,s^d) depends on a bound d on the dividend’s individual degree; the unrestricted-individual-degree question is explicitly distinguished.')])
save(i,dict(title='Deterministic divisibility testing by a constant-degree polynomial',formal='For every fixed integer δ≥2, is there a deterministic algorithm using poly(n,s,d) arithmetic operations over Q that, given an explicitly s-sparse polynomial f∈Q[x_1,…,x_n] of total degree at most d and a nonzero polynomial g∈Q[x_1,…,x_n] of total degree at most δ, decides whether g divides f?',definitions='A sparse representation of f lists its nonzero rational coefficients and corresponding nonnegative integer exponent vectors; s is the number of listed monomials and d bounds the sum of exponents in each monomial. The candidate divisor g is supplied by its coefficients and exponent vectors; because δ is fixed, it has at most binomial(n+δ,δ) monomials, so dense and sparse explicit encodings are polynomially related. Divisibility means that a polynomial h∈Q[x_1,…,x_n] exists with f=gh. The quotient need not be sparse and need not be output. The polynomial running-time exponent may depend on the fixed δ, but not on the input n,s,d. The source counts exact arithmetic operations over Q at unit cost. In particular, the requested bound is polynomial in the numerical degree d, not merely in log d, and is not a bound on rational-coefficient bit complexity. There is no promise that g is irreducible. The cases f=0 or nonzero constant g have immediate affirmative answers; the first unsettled divisor degree is two.',question_type='yes_no',answer_criterion='Give a deterministic divisibility decision algorithm with the stated polynomial arithmetic cost for every fixed δ, or establish an obstruction to that precise guarantee. Randomized testing, quasipolynomial time, or a bound requiring the dividend f to have constant individual degree does not answer the question.',context_blocks=[b('The candidate factor is part of the input','This problem verifies one supplied potential divisor. It does not ask to discover all irreducible factors or to decide whether f itself is irreducible. The nonlinear candidate can already be quadratic.'),b('A short polynomial need not have a short quotient','For example, x^D−1 is sparse and divisible by x−1, but its quotient has D terms. Sparsity of f therefore gives no promise that a quotient has few monomials relative to the sparse input length.'),b('The known running time leaves a gap','Deterministic polynomial-time testing is available for linear divisors; for arbitrary fixed-degree nonlinear divisors, the cited general sparse-dividend result is quasipolynomial. The target removes that quasipolynomial overhead.', 'primary'),b('Recent bounded-individual-degree factoring is a different guarantee','The 2026 result gives polynomial time when every variable’s degree in the dividend is a fixed constant. Here only the divisor g has fixed total degree: the dividend can have arbitrarily large individual degrees up to d.', 'bounded_individual')],why='Tests whether even a supplied low-degree factor of a sparse multivariate polynomial can be verified efficiently without randomness, a basic obstruction in deterministic factorization.',progress=[dict(date='2015',text='Forbes gives deterministic quasipolynomial-time divisibility testing for constant-degree divisors of sparse polynomials.',citation='forbes'),dict(date='2024',text='Dutta, Sinhababu and Thierauf retain polynomial-time testing as open even for quadratic divisors.',citation='primary'),dict(date='2026',text='Chuyoon and Shpilka give new factorization guarantees under bounded individual degree of the dividend, while distinguishing the unrestricted case.',citation='bounded_individual')],references=refs,status='source_open',status_note='Source field, cost model and missing predicate checked, together with the 2024 full-version record, the 2026 bounded-individual-degree result and arXiv:2606.12130 on finite-field sparse divisibility. The latter uses a different field and unrestricted divisor degrees. No resolution of this fixed-degree-divisor rational-arithmetic target was located through 12 September 2026.',model_self_contained=True,requires_context=False,importance=imp(c,'A basic derandomization question linking sparse divisibility and low-degree factorization.'),review_note='Recovered divisibility rather than irreducibility, and retained the source’s numerical-degree and unit-cost arithmetic model. Distinguished bounded degree of the divisor from bounded individual degree of the dividend.',working_summary=sm(['The input is a sparse multivariate polynomial f and a proposed low-degree divisor g.','The question is whether divisibility can always be decided deterministically in polynomially many rational arithmetic operations.','Even quadratic g remains the key case.','The time bound may be polynomial in the numerical degree of f, and no sparse quotient is promised.','New results for dividends of bounded individual degree do not settle the unrestricted dividend case here.'],['primary','forbes','bounded_individual'])),notes=['Recovered the missing divisibility predicate and exact candidate/dividend roles.','Specified Q, unit-cost arithmetic, numerical total degree and fixed divisor degree.','Separated the target from 2026 bounded-individual-degree and finite-field results.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2411.17330','https://arxiv.org/abs/2606.12130'])
